function region_counts(N):
    p <- array of length N+1;  c <- array of length N+1
    p[0] <- 1;  c[0] <- 1
    for n from 0 to N-1:
        p[n+1] <- p[n] + (n + 1)      # first-difference recurrence
        c[n+1] <- c[n] + p[n]         # layer recurrence (dimension lift)
    return (p, c)

function H(d, n):
    total <- 0;  binom <- 1        # binom holds C(n, k)
    for k from 0 to min(d, n):
        total <- total + binom
        binom <- binom * (n - k) / (k + 1)   # C(n, k+1) from C(n, k)
    return total

function caterer_is_odd(n):
    r <- n mod 4
    return (r = 0) or (r = 3)

